// T9 version 1. Stock K1, no overlay. Observe the shooting-screen composite
// at rest, during S1, and after release, then set Small at a non-centre
// position with native keys on the direct screen and observe again.
// Draw hooks only record. They call the lab's existing observer, which
// runs the draw instruction. No firmware byte is written.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/obs_k1_v1.mjs om-emu
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from '../../ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/zone_session_k1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/obs_k1_v1.mjs om-emu\n');
  process.exit(2);
}

const GET = 0x60063380;
const SET_API = 0x50ac4afe;
const CONVERTER = 0x604050e5;
const CONSUMER = 0xa33ca384;
const CAPTURE = 0xa33f2ce0;
const DIRTY = 0xa33f2cea;
const ZONE_PATH = 'ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/zone_session_k1.mjs';
const OUT = resolve('work/out/obs-k1-v1.jsonl');
const lines = [];

function shaFile(p) {
  const data = readFileSync(p);
  return { path: p, sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length };
}

function emit(row) {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify({ id: row.id, pass: row.pass, problems: row.problems, step: row.step }));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
}

const s16 = (v) => {
  const n = v & 0xffff;
  return n & 0x8000 ? n - 0x10000 : n;
};
const hex = (v) => '0x' + (v >>> 0).toString(16);

function scan(rgb, w, h) {
  const x0 = Math.floor(w * 0.18);
  const x1 = Math.floor(w * 0.82);
  const y0 = Math.floor(h * 0.12);
  const y1 = Math.floor(h * 0.78);
  let n = 0;
  let minX = w;
  let minY = h;
  let maxX = -1;
  let maxY = -1;
  let peak = 0;
  const hist = new Map();
  for (let y = y0; y < y1; y++) {
    for (let x = x0; x < x1; x++) {
      const i = (y * w + x) * 3;
      const r = rgb[i];
      const g = rgb[i + 1];
      const b = rgb[i + 2];
      const mx = r > g ? (r > b ? r : b) : (g > b ? g : b);
      if (mx > peak) peak = mx;
      const mn = r < g ? (r < b ? r : b) : (g < b ? g : b);
      if (mx >= 28 && mx - mn <= 48) {
        n += 1;
        if (x < minX) minX = x;
        if (y < minY) minY = y;
        if (x > maxX) maxX = x;
        if (y > maxY) maxY = y;
        const key = r + ',' + g + ',' + b;
        hist.set(key, (hist.get(key) || 0) + 1);
      }
    }
  }
  const colours = [...hist.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6)
    .map(([rgbKey, count]) => ({ rgb: rgbKey, count }));
  const hx0 = Math.floor(w * 0.25);
  const hx1 = Math.floor(w * 0.75);
  const hy0 = Math.floor(h * 0.20);
  const hy1 = Math.floor(h * 0.75);
  const hash = createHash('sha256');
  for (let y = hy0; y < hy1; y++) hash.update(rgb.subarray((y * w + hx0) * 3, (y * w + hx1) * 3));
  return {
    peak,
    greyCount: n,
    box: n ? { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 } : null,
    colours,
    centerWindow: { x: hx0, y: hy0, w: hx1 - hx0, h: hy1 - hy0 },
    centerSha256: hash.digest('hex'),
  };
}

function summarizeDraws(hits, w, h) {
  const counts = new Map();
  for (const hit of hits) {
    const key = [hit.op, hit.caller, hit.x, hit.y, hit.w, hit.h, hit.colour ?? '', hit.data ?? '', hit.layer, hit.error ?? ''].join('|');
    const prev = counts.get(key);
    if (prev) prev.n += 1;
    else counts.set(key, { ...hit, n: 1 });
  }
  const rows = [...counts.values()];
  const cx0 = Math.floor(w * 0.15);
  const cx1 = Math.floor(w * 0.85);
  const cy0 = Math.floor(h * 0.10);
  const cy1 = Math.floor(h * 0.82);
  const center = rows.filter((row) => {
    if (row.error) return false;
    const x2 = row.x + (row.w || 0);
    const y2 = row.y + (row.h || 0);
    const overlaps = row.x < cx1 && x2 > cx0 && row.y < cy1 && y2 > cy0;
    const sized = row.w > 1 && row.w < 420 && row.h > 1 && row.h < 420;
    return overlaps && sized;
  }).sort((a, b) => a.y - b.y || a.x - b.x || a.w - b.w);
  const callers = [...new Set(center.map((row) => row.caller))].slice(0, 40);
  return { total: hits.length, unique: rows.length, centerCount: center.length, callers, center: center.slice(0, 80) };
}

try {
  const zoneHash = shaFile(ZONE_PATH);
  emit({
    id: 'v1-plan', step: 'plan', pass: true, problems: [],
    note: 'Stock K1, no overlay. TFT shooting screen at rest, S1 held, and after release. Then native direct-screen keys: two main-dial detents to Small (0x99a1[1]=2) and one Right to position 529. Draw recording is observe-only.',
    zoneSession: zoneHash,
    expected: { subject: 0, focus289: 0, focus25: 0, small: 2, position: 529, size: [3, 3] },
  });

  const result = await runZone({
    checkout,
    outPath: 'work/out/session-obs-k1-v1.jsonl',
    tag: 'obs-k1-v1',
    candidate: false,
    help: false,
    rowLabel: false,
    overlayCsv: null,
    fatalShots: true,
    explanation: 'v1 stock K1. No overlay and no firmware write. Native TAKE_FOCUS bring-up matches the T6 K1 session. Draw wrappers only record.',
    change: 'none',
    async drive(ctx) {
      const { A } = await import(pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href);
      const { GPI_DRAW_RECT, GPI_DRAW_BITMAP, s16: labS16 } = await import(pathToFileURL(resolve(checkout, 'emu/src/lab/menu.mjs')).href);
      const { words_to_rgb } = await import(pathToFileURL(resolve(checkout, 'emu/src/lab/display.mjs')).href);
      const { write_png } = await import(pathToFileURL(resolve(checkout, 'emu/checks/lib/png.mjs')).href);
      const API_SET = A(SET_API);
      let armed = false;
      const hits = [];
      const record = (op, r) => {
        if (!armed || hits.length > 8000) return;
        try {
          if (op === 'rect') {
            const [h, colour, layer] = ctx.l.stack_args(r, 3);
            hits.push({
              op, caller: hex(r.mdr), x: labS16(r.d0), y: labS16(r.d1), w: labS16(r.a1), h: s16(h),
              colour: colour >>> 0, layer: layer & 0xffff,
            });
          } else {
            const [w, h, , , layer] = ctx.l.stack_args(r, 5);
            hits.push({
              op, caller: hex(r.mdr), x: labS16(r.d0), y: labS16(r.d1), w: s16(w), h: s16(h),
              data: hex(r.a1), layer: layer & 0xffff,
            });
          }
        } catch (e) {
          hits.push({ op, caller: hex(r.mdr), error: String(e && e.message || e) });
        }
      };
      let wrapError = null;
      try {
        ctx.l.wrap(GPI_DRAW_RECT, (prev) => (hle, r) => { record('rect', r); prev(hle, r); }, 'obs-t9-rect-v1');
        ctx.l.wrap(GPI_DRAW_BITMAP, (prev) => (hle, r) => { record('bitmap', r); prev(hle, r); }, 'obs-t9-bitmap-v1');
      } catch (e) {
        wrapError = String(e && e.message || e);
      }
      emit({
        id: 'v1-draw-hooks', step: 'hooks', pass: wrapError === null, problems: wrapError ? ['wrap'] : [],
        expect: { wrap: 'installed' }, actual: { wrap: wrapError ? 'failed' : 'installed', error: wrapError },
        rect: hex(GPI_DRAW_RECT), bitmap: hex(GPI_DRAW_BITMAP),
        label: 'observe-only wrappers around the lab draw observers',
      });

      function readKey(key, index) {
        return ctx.l.call(ctx.native(GET), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff;
      }
      function cells() {
        return {
          k99a1: Array.from({ length: 8 }, (_, i) => readKey(0x99a1, i)),
          k9a41: readKey(0x9a41, 0),
          k84d1: readKey(0x84d1, 0),
          k88b2: readKey(0x88b2, 0),
          k5962: Array.from({ length: 6 }, (_, i) => readKey(0x5962, i)),
          k1dd1: Array.from({ length: 10 }, (_, i) => readKey(0x1dd1, i)),
          k1e71: readKey(0x1e71, 0),
        };
      }
      function bytesAt(addr, n) {
        return Array.from(ctx.l.sim.read(addr, n));
      }
      function view() {
        const id = ctx.l.state();
        return {
          screen: ctx.s.screen(),
          device: ctx.s.device,
          state: hex(id),
          stateName: ctx.l.state_names.get(id) ?? null,
        };
      }
      function snapshot(id, expect) {
        const mark = ctx.l.draw_log.length;
        hits.length = 0;
        armed = true;
        ctx.idle(280);
        armed = false;
        let frameError = null;
        let fr = null;
        try {
          fr = ctx.s.frame('boundary');
        } catch (e) {
          frameError = String(e && e.message || e);
        }
        const problems = [];
        if (!fr) problems.push('screenshot');
        const where = view();
        const now = cells();
        const target = bytesAt(CONSUMER, 10);
        const capture = bytesAt(CAPTURE, 10);
        const dirty = ctx.l.sim.read(DIRTY, 1)[0];
        const focus = { s289: ctx.s.get(289), s25: ctx.s.get(25) };
        if (expect.screen !== undefined && where.screen !== expect.screen) problems.push('screen');
        if (expect.subject !== undefined && now.k1e71 !== expect.subject) problems.push('subject');
        if (expect.focus289 !== undefined && focus.s289 !== expect.focus289) problems.push('focus289');
        if (expect.focus25 !== undefined && focus.s25 !== expect.focus25) problems.push('focus25');
        if (expect.zone !== undefined && now.k99a1[1] !== expect.zone) problems.push('zone');
        if (expect.position !== undefined && now.k5962[1] !== expect.position) problems.push('position');
        let file = null;
        let sha = null;
        let pixels = null;
        let draws = null;
        if (fr) {
          const rgb = words_to_rgb(fr[2]);
          file = resolve('work/out/obs-k1-v1-' + id + '.png');
          write_png(file, fr[0], fr[1], rgb);
          sha = shaFile(file);
          pixels = scan(rgb, fr[0], fr[1]);
          draws = summarizeDraws(hits, fr[0], fr[1]);
        }
        const added = ctx.l.draw_log.slice(mark).filter((d) => d.op === 'rect' || d.op === 'bitmap').length;
        const row = {
          id: 'v1-' + id, step: id, pass: problems.length === 0, problems,
          expect, actual: { screen: where.screen, subject: now.k1e71, focus, zone: now.k99a1[1], position: now.k5962[1], size: [now.k1dd1[0], now.k1dd1[1]] },
          where, cells: now, target, capture, dirty, file: file ? 'work/out/obs-k1-v1-' + id + '.png' : null,
          png: sha, frameError, pixels, draws, drawLogAdded: added,
        };
        emit(row);
        if (problems.length) throw new Error(id + ' ' + problems.join(',') + (frameError ? ' ' + frameError : ''));
        return row;
      }

      ctx.bringUp();
      ctx.s.switch_input('lever', 1);
      ctx.s.camapp.pump();
      ctx.idle(400);
      const grouped = true;
      const argument = ctx.l.call(ctx.native(CONVERTER), { d0: 289, d1: 0 }, null, null, 200000).d0 >>> 0;
      ctx.l.call(API_SET, { d0: 289, d1: grouped ? argument : 0 }, null, null, 200000);
      ctx.idle(400);
      const focusActual = { s289: ctx.s.get(289), s25: ctx.s.get(25) };
      const focusProblems = [];
      if (focusActual.s289 !== 0) focusProblems.push('focus289');
      if (focusActual.s25 !== 0) focusProblems.push('focus25');
      emit({
        id: 'v1-focus', step: 'focus', pass: focusProblems.length === 0, problems: focusProblems,
        expect: { s289: 0, s25: 0 }, actual: focusActual,
        note: 'S-AF through the public setter, sid 289. Test setup on a stock image. No overlay.',
      });
      if (focusProblems.length) throw new Error('focus ' + focusProblems.join(','));

      ctx.press('menu');
      for (let i = 0; i < 20; i++) ctx.press('left');
      const menu = ctx.shot('subject');
      const subject = readKey(0x1e71, 0);
      const subjectProblems = [];
      if (menu.highlight !== 'Subject Detection') subjectProblems.push('highlight');
      if (!menu.texts.includes('Off')) subjectProblems.push('off-text');
      if (subject !== 0) subjectProblems.push('subject');
      emit({
        id: 'v1-subject', step: 'subject', pass: subjectProblems.length === 0, problems: subjectProblems,
        expect: { highlight: 'Subject Detection', offText: true, subject: 0 },
        actual: { highlight: menu.highlight, texts: menu.texts, subject },
        file: menu.file,
        note: '0x1e71[0] is MODE_SUBJECT_DETECT. The stock screen text is the Off readback.',
      });
      if (subjectProblems.length) throw new Error('subject ' + subjectProblems.join(','));
      for (let i = 0; i < 8 && ctx.s.screen() !== 'shooting'; i++) ctx.press('menu');
      if (ctx.s.screen() !== 'shooting') throw new Error('did not return to shooting after subject');

      const rest = snapshot('rest', { screen: 'shooting', subject: 0, focus289: 0, focus25: 0, zone: 0, position: 526 });
      ctx.key('s1', 'down');
      const held = snapshot('s1-held', { screen: 'shooting', subject: 0, focus289: 0, focus25: 0 });
      ctx.key('s1', 'up');
      const released = snapshot('s1-up', { screen: 'shooting', subject: 0, focus289: 0, focus25: 0, zone: 0, position: 526 });

      ctx.press('up');
      const opened = view();
      const openCells = cells();
      const openProblems = [];
      if (opened.screen !== 'direct') openProblems.push('screen');
      emit({
        id: 'v1-direct-open', step: 'direct-open', pass: openProblems.length === 0, problems: openProblems,
        expect: { screen: 'direct' }, actual: opened, cells: openCells,
        note: 'Up from shooting opens ID_ST_MENU_DIRECT. The text layer is empty, so this step uses s.screen() and does not read texts.',
      });
      if (openProblems.length) throw new Error('direct-open ' + openProblems.join(','));

      const dials = [];
      for (let i = 0; i < 4 && cells().k99a1[1] !== 2; i++) {
        ctx.s.dial_input('main', 1);
        ctx.s.camapp.pump();
        ctx.idle(400);
        const now = cells();
        dials.push({ detent: i + 1, zone: now.k99a1[1], kind: now.k84d1, size: [now.k1dd1[0], now.k1dd1[1]], position: now.k5962[1] });
      }
      const afterDial = cells();
      const dialProblems = [];
      if (afterDial.k99a1[1] !== 2) dialProblems.push('zone');
      if (afterDial.k1dd1[0] !== 3 || afterDial.k1dd1[1] !== 3) dialProblems.push('size');
      emit({
        id: 'v1-direct-small', step: 'direct-small', pass: dialProblems.length === 0, problems: dialProblems,
        expect: { zone: 2, size: [3, 3] },
        actual: { zone: afterDial.k99a1[1], size: [afterDial.k1dd1[0], afterDial.k1dd1[1]], kind: afterDial.k84d1 },
        dials,
        note: 'Native main dial on the direct screen. Stock order is All 0, Single 1, Small 2. Small current size is 3 by 3.',
      });
      if (dialProblems.length) throw new Error('direct-small ' + dialProblems.join(','));

      ctx.press('right');
      const movedCells = cells();
      const moveProblems = [];
      if (movedCells.k5962[1] !== 529) moveProblems.push('position');
      if (movedCells.k88b2 !== 529) moveProblems.push('frame');
      if (movedCells.k99a1[1] !== 2) moveProblems.push('zone');
      emit({
        id: 'v1-direct-move', step: 'direct-move', pass: moveProblems.length === 0, problems: moveProblems,
        expect: { zone: 2, position: 529, frame: 529 },
        actual: { zone: movedCells.k99a1[1], position: movedCells.k5962[1], frame: movedCells.k88b2 },
        cells: movedCells,
        note: 'One Right on a movable zone adds 3 to 0x5962[1] and 0x88b2. 526 plus 3 is 529.',
      });
      if (moveProblems.length) throw new Error('direct-move ' + moveProblems.join(','));
      snapshot('direct-small-529', { screen: 'direct', subject: 0, zone: 2, position: 529 });

      ctx.press('ok');
      ctx.idle(400);
      const back = view();
      const backProblems = [];
      if (back.screen !== 'shooting') backProblems.push('screen');
      emit({
        id: 'v1-direct-ok', step: 'direct-ok', pass: backProblems.length === 0, problems: backProblems,
        expect: { screen: 'shooting' }, actual: back, cells: cells(),
        note: 'OK leaves the direct screen for shooting and keeps the change index.',
      });
      if (backProblems.length) throw new Error('direct-ok ' + backProblems.join(','));

      const movedRest = snapshot('small-rest', { screen: 'shooting', subject: 0, focus289: 0, focus25: 0, zone: 2, position: 529 });
      ctx.key('s1', 'down');
      const movedHeld = snapshot('small-s1-held', { screen: 'shooting', subject: 0, focus289: 0, focus25: 0, zone: 2, position: 529 });
      ctx.key('s1', 'up');
      const movedUp = snapshot('small-s1-up', { screen: 'shooting', subject: 0, focus289: 0, focus25: 0, zone: 2, position: 529 });

      const frameLike = [rest, held, released, movedRest, movedHeld, movedUp].filter((row) => row.pixels && row.pixels.greyCount > 0);
      emit({
        id: 'v1-compare', step: 'compare', pass: true, problems: [],
        restCenter: rest.pixels && rest.pixels.centerSha256,
        heldCenter: held.pixels && held.pixels.centerSha256,
        upCenter: released.pixels && released.pixels.centerSha256,
        smallRestCenter: movedRest.pixels && movedRest.pixels.centerSha256,
        smallHeldCenter: movedHeld.pixels && movedHeld.pixels.centerSha256,
        smallUpCenter: movedUp.pixels && movedUp.pixels.centerSha256,
        restBox: rest.pixels && rest.pixels.box,
        smallRestBox: movedRest.pixels && movedRest.pixels.box,
        restPng: rest.png && rest.png.sha256,
        smallRestPng: movedRest.png && movedRest.png.sha256,
        centerChanged: !!(rest.pixels && movedRest.pixels && rest.pixels.centerSha256 !== movedRest.pixels.centerSha256),
        s1ChangedCenter: !!(rest.pixels && held.pixels && rest.pixels.centerSha256 !== held.pixels.centerSha256),
        frameLikeCount: frameLike.length,
        callersAtRest: rest.draws && rest.draws.callers,
        callersAtSmall: movedRest.draws && movedRest.draws.callers,
      });

      if (frameLike.length === 0) {
        ctx.s.switch_input('eye', 1);
        ctx.s.camapp.pump();
        ctx.idle(800);
        snapshot('evf-small-rest', { screen: 'shooting', subject: 0, zone: 2, position: 529 });
        ctx.press('info');
        snapshot('evf-info', { subject: 0 });
        ctx.s.switch_input('lv');
        ctx.s.camapp.pump();
        ctx.idle(800);
        snapshot('lv-after-evf', { subject: 0 });
        emit({
          id: 'v1-alternatives', step: 'alternatives', pass: true, problems: [],
          note: 'No grey mark in the TFT centre window. Tried EVF, INFO, and the LV display key.',
        });
      } else {
        emit({
          id: 'v1-alternatives', step: 'alternatives', pass: true, problems: [],
          note: 'A grey mark is in the TFT centre window, so the EVF and display-key alternatives are not required for a missing frame.',
          frameLikeCount: frameLike.length,
        });
      }
    },
  });
  emit({ id: 'v1-done', step: 'done', pass: result.ok, problems: result.ok ? [] : ['session'], ok: result.ok, failed: result.failed });
  if (!result.ok) process.exit(1);
} catch (e) {
  emit({ id: 'v1-done', step: 'done', pass: false, problems: ['exception'], ok: false, error: String(e && e.stack ? e.stack : e) });
  process.exit(1);
}
